import os
import re
import time
import unicodedata
import hashlib
import secrets
from functools import wraps
from flask import Flask, request, session, jsonify, abort, g
import bcrypt
import sqlite3

app = Flask(__name__)
app.secret_key = os.environ['FLASK_SECRET_KEY']

DB_PATH = os.environ.get('DB_PATH', '/var/app/users.db')
MAX_LOGIN_ATTEMPTS = 5
LOCKOUT_DURATION = 900  # 15 minutes

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

@app.teardown_appcontext
def close_db(exc):
    db = g.pop('db', None)
    if db is not None:
        db.close()

def normalize_username_for_storage(username):
    """Normalize username to canonical form for storage.
    Uses NFC normalization to ensure consistent representation."""
    username = username.strip().lower()
    # NFC: Canonical Decomposition followed by Canonical Composition
    normalized = unicodedata.normalize('NFC', username)
    return normalized

def normalize_username_for_comparison(username):
    """Normalize username for comparison/lookup operations.
    Uses compatibility normalization to handle equivalent representations."""
    username = username.strip().lower()
    # NFKC: Compatibility Decomposition followed by Canonical Composition
    # This maps compatibility-equivalent characters to their canonical forms
    normalized = unicodedata.normalize('NFKC', username)
    return normalized

def validate_username_format(username):
    """Validate username meets security requirements."""
    if not username or len(username) < 3 or len(username) > 32:
        return False, "Username must be 3-32 characters"
    # Allow unicode letters, digits, underscores, hyphens
    if not re.match(r'^[\w\-]+$', username, re.UNICODE):
        return False, "Username contains invalid characters"
    # Block control characters and zero-width characters
    for ch in username:
        cat = unicodedata.category(ch)
        if cat.startswith('C'):  # Control characters
            return False, "Username contains control characters"
        if cat == 'Cf':  # Format characters (zero-width etc)
            return False, "Username contains format characters"
    return True, None

def check_rate_limit(identifier):
    """Check if identifier is rate-limited."""
    db = get_db()
    cutoff = time.time() - LOCKOUT_DURATION
    row = db.execute(
        'SELECT COUNT(*) as cnt FROM login_attempts WHERE identifier = ? AND timestamp > ?',
        (identifier, cutoff)
    ).fetchone()
    return row['cnt'] < MAX_LOGIN_ATTEMPTS

def record_login_attempt(identifier, success):
    """Record a login attempt for rate limiting."""
    db = get_db()
    db.execute(
        'INSERT INTO login_attempts (identifier, timestamp, success) VALUES (?, ?, ?)',
        (identifier, time.time(), success)
    )
    if success:
        db.execute(
            'DELETE FROM login_attempts WHERE identifier = ? AND success = 0',
            (identifier,)
        )
    db.commit()

def require_csrf(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if request.method in ('POST', 'PUT', 'DELETE'):
            token = request.headers.get('X-CSRF-Token')
            if not token or not secrets.compare_digest(token, session.get('csrf_token', '')):
                abort(403)
        return f(*args, **kwargs)
    return decorated

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            abort(401)
        db = get_db()
        user = db.execute('SELECT * FROM users WHERE id = ?', (session['user_id'],)).fetchone()
        if not user:
            session.clear()
            abort(401)
        g.current_user = dict(user)
        return f(*args, **kwargs)
    return decorated

@app.route('/api/register', methods=['POST'])
@require_csrf
def register():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')
    email = data.get('email', '')

    # Validate username format
    valid, err = validate_username_format(username)
    if not valid:
        return jsonify({'error': err}), 400

    # Validate password strength
    if len(password) < 12:
        return jsonify({'error': 'Password must be at least 12 characters'}), 400

    # Normalize for storage
    stored_username = normalize_username_for_storage(username)

    # Check if username already exists using comparison normalization
    lookup_username = normalize_username_for_comparison(username)
    db = get_db()
    existing = db.execute(
        'SELECT id FROM users WHERE username = ?',
        (lookup_username,)
    ).fetchone()

    if existing:
        return jsonify({'error': 'Username already taken'}), 409

    # Hash password with bcrypt
    password_hash = bcrypt.hashpw(password.encode('utf-8'), bcrypt.gensalt(rounds=12))

    # Store user with storage-normalized username
    try:
        db.execute(
            'INSERT INTO users (username, password_hash, email, created_at) VALUES (?, ?, ?, ?)',
            (stored_username, password_hash.decode('utf-8'), email, time.time())
        )
        db.commit()
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already taken'}), 409

    return jsonify({'message': 'Registration successful'}), 201

@app.route('/api/login', methods=['POST'])
@require_csrf
def login():
    data = request.get_json()
    if not data:
        return jsonify({'error': 'Invalid request'}), 400

    username = data.get('username', '')
    password = data.get('password', '')

    # Rate limiting by IP + username
    rate_key = f"{request.remote_addr}:{username}"
    if not check_rate_limit(rate_key):
        return jsonify({'error': 'Too many attempts. Try again later.'}), 429

    # Normalize username for lookup
    lookup_username = normalize_username_for_comparison(username)

    db = get_db()
    user = db.execute(
        'SELECT * FROM users WHERE username = ?',
        (lookup_username,)
    ).fetchone()

    if not user:
        # Constant-time fake check to prevent user enumeration
        bcrypt.hashpw(b'dummy_password_check', bcrypt.gensalt(rounds=12))
        record_login_attempt(rate_key, False)
        return jsonify({'error': 'Invalid credentials'}), 401

    if bcrypt.checkpw(password.encode('utf-8'), user['password_hash'].encode('utf-8')):
        record_login_attempt(rate_key, True)
        session.regenerate()
        session['user_id'] = user['id']
        session['csrf_token'] = secrets.token_hex(32)
        return jsonify({
            'message': 'Login successful',
            'csrf_token': session['csrf_token'],
            'user': {'id': user['id'], 'username': user['username']}
        }), 200
    else:
        record_login_attempt(rate_key, False)
        return jsonify({'error': 'Invalid credentials'}), 401

@app.route('/api/profile', methods=['GET'])
@require_auth
def get_profile():
    user = g.current_user
    return jsonify({
        'id': user['id'],
        'username': user['username'],
        'email': user['email']
    })

@app.route('/api/profile/change-password', methods=['POST'])
@require_auth
@require_csrf
def change_password():
    data = request.get_json()
    current_password = data.get('current_password', '')
    new_password = data.get('new_password', '')

    if len(new_password) < 12:
        return jsonify({'error': 'Password must be at least 12 characters'}), 400

    user = g.current_user
    if not bcrypt.checkpw(current_password.encode('utf-8'), user['password_hash'].encode('utf-8')):
        return jsonify({'error': 'Current password incorrect'}), 403

    new_hash = bcrypt.hashpw(new_password.encode('utf-8'), bcrypt.gensalt(rounds=12))
    db = get_db()
    db.execute(
        'UPDATE users SET password_hash = ? WHERE id = ?',
        (new_hash.decode('utf-8'), user['id'])
    )
    db.commit()

    return jsonify({'message': 'Password changed successfully'}), 200

@app.route('/api/user/lookup', methods=['GET'])
@require_auth
def lookup_user():
    """Look up a user by username for messaging/friend requests."""
    username = request.args.get('username', '')
    if not username:
        return jsonify({'error': 'Username required'}), 400

    # Use comparison normalization for consistent lookups
    lookup_username = normalize_username_for_comparison(username)

    db = get_db()
    user = db.execute(
        'SELECT id, username, email FROM users WHERE username = ?',
        (lookup_username,)
    ).fetchone()

    if not user:
        return jsonify({'error': 'User not found'}), 404

    return jsonify({'id': user['id'], 'username': user['username']})

